// Fit check: the OLT cage lane switched at run time between GPON (gen_ip.sh olt: 2488.32, VCXO 155.52 MHz) and
// 1.25 Gb/s (olt_1g25: EPON OLT or 1000BASE-X, XO 156.25 MHz) by the GTS dynamic reconfiguration controller, each
// profile on its own refclk, PMA clocking; dr_top is generated by quartus_tlg (fit.sh). Under DR the RX words come on
// the profile's own rx_clkout. Counters keep both profiles' datapaths alive.
module dr_lane (
    input  wire       clk,          // management, 100 MHz
    input  wire       pon_refclk,
    input  wire       eth_refclk,
    input  wire       reset,
    output wire       olt_tx_p,
    output wire       olt_tx_n,
    input  wire       olt_rx_p,
    input  wire       olt_rx_n,
    input  wire [6:0] dr_address,
    input  wire       dr_read,
    input  wire       dr_write,
    input  wire [31:0] dr_writedata,
    output wire [31:0] dr_readdata,
    output wire       dr_readdatavalid,
    output wire       dr_waitrequest,
    output wire [14:0] profile,
    output wire [7:0] status
);
    wire grant, request, cu_clk;
    srcss srcss (.o_src_rs_grant(grant), .i_src_rs_priority(1'b0), .i_src_rs_req(request), .o_pma_cu_clk(cu_clk),
                 .i_src_rs_refclk_status_bus(10'b0), .o_refclk_fail_status(), .o_refclk_on_ack(), .i_refclk_on(10'b0),
                 .o_src_rs_refclk_cmd_bus());

    wire [1:0]  sel;
    wire        pause_request, pause_grant, lavmm_write, lavmm_read, lavmm_rdata_valid, lavmm_waitreq, lavmm_rstn;
    wire [20:0] lavmm_addr;
    wire [3:0]  lavmm_be;
    wire [31:0] lavmm_wdata, lavmm_rdata;
    dr_ctrl dr_ctrl (.i_rst_n(~reset), .i_csr_clk(clk), .i_cpu_clk(clk), .o_profile_id(profile), .o_in_progress(),
        .o_err_status(), .o_fast_sim_clk_sel(), .i_host_avmm_address(dr_address), .o_host_avmm_readdatavalid(dr_readdatavalid),
        .i_host_avmm_read(dr_read), .i_host_avmm_write(dr_write), .o_host_avmm_readdata(dr_readdata),
        .i_host_avmm_writedata(dr_writedata), .o_host_avmm_waitrequest(dr_waitrequest), .o_one_hot_sel(sel),
        .o_src_pause_request(pause_request), .i_src_pause_grant(pause_grant), .o_ch0_lavmm_addr(lavmm_addr),
        .o_ch0_lavmm_be(lavmm_be), .o_ch0_lavmm_write(lavmm_write), .o_ch0_lavmm_read(lavmm_read),
        .o_ch0_lavmm_wdata(lavmm_wdata), .i_ch0_lavmm_rdata(lavmm_rdata), .i_ch0_lavmm_rdata_valid(lavmm_rdata_valid),
        .i_ch0_lavmm_waitreq(lavmm_waitreq), .o_ch0_lavmm_rstn(lavmm_rstn));

    wire gpon_clk, gpon_rx_clk, eth_tx_clk, eth_rx_clk;
    reg  [7:0] gpon_count, eth_count;
    always @(posedge gpon_clk) gpon_count <= gpon_count + 8'd1;
    always @(posedge eth_tx_clk) eth_count <= eth_count + 8'd1;
    wire [79:0] gpon_rx, eth_rx;
    reg  [1:0] rx_bit;
    always @(posedge gpon_rx_clk) rx_bit[0] <= ^gpon_rx[7:0];
    always @(posedge eth_rx_clk) rx_bit[1] <= ^eth_rx[9:0];
    assign status = {gpon_count[7:5], eth_count[7:5], rx_bit};

    dr_top dr_top (
        .i_dr_lavmm_addr_ch0(lavmm_addr), .i_dr_lavmm_be_ch0(lavmm_be), .i_dr_lavmm_clk_ch0(clk),
        .i_dr_lavmm_read_ch0(lavmm_read), .i_dr_lavmm_rstn_ch0(lavmm_rstn), .i_dr_lavmm_wdata_ch0(lavmm_wdata),
        .i_dr_lavmm_write_ch0(lavmm_write), .o_dr_lavmm_rdata_ch0(lavmm_rdata), .o_dr_lavmm_rdata_valid_ch0(lavmm_rdata_valid),
        .o_dr_lavmm_waitreq_ch0(lavmm_waitreq), .i_pma_cu_clk_bank0(cu_clk), .i_rs_grant_ch0(grant), .o_rs_request_ch0(request),
        .i_src_pause_request_ch0(pause_request), .o_src_pause_grant_ch0(pause_grant), .one_hot_sel(sel),
        .i_rx_serial_data_p_ch0(olt_rx_p), .i_rx_serial_data_n_ch0(olt_rx_n),
        .o_tx_serial_data_p_ch0(olt_tx_p), .o_tx_serial_data_n_ch0(olt_tx_n),
        // GPON profile
        .i_tx_pll_refclk_p_olt_inst(pon_refclk), .i_rx_cdr_refclk_p_olt_inst(pon_refclk),
        .i_tx_coreclkin_olt_inst(gpon_clk), .i_rx_coreclkin_olt_inst(gpon_rx_clk),
        .o_tx_clkout_olt_inst(gpon_clk), .o_rx_clkout_olt_inst(gpon_rx_clk),
        .i_tx_reset_olt_inst(reset), .i_rx_reset_olt_inst(reset), .o_tx_reset_ack_olt_inst(),
        .o_rx_reset_ack_olt_inst(), .o_tx_ready_olt_inst(), .o_rx_ready_olt_inst(),
        .o_tx_pll_locked_olt_inst(), .o_rx_is_lockedtodata_olt_inst(), .o_rx_is_lockedtoref_olt_inst(),
        .i_rx_set_locktoref_olt_inst(1'b0), .i_tx_parallel_data_olt_inst({72'b0, gpon_count}),
        .o_rx_parallel_data_olt_inst(gpon_rx),
        // 1.25 Gb/s profile
        .i_tx_pll_refclk_p_olt_1g25_inst(eth_refclk), .i_rx_cdr_refclk_p_olt_1g25_inst(eth_refclk),
        .i_tx_coreclkin_olt_1g25_inst(eth_tx_clk), .i_rx_coreclkin_olt_1g25_inst(eth_rx_clk),
        .o_tx_clkout_olt_1g25_inst(eth_tx_clk), .o_rx_clkout_olt_1g25_inst(eth_rx_clk),
        .i_tx_reset_olt_1g25_inst(reset), .i_rx_reset_olt_1g25_inst(reset), .o_tx_reset_ack_olt_1g25_inst(),
        .o_rx_reset_ack_olt_1g25_inst(), .o_tx_ready_olt_1g25_inst(), .o_rx_ready_olt_1g25_inst(),
        .o_tx_pll_locked_olt_1g25_inst(), .o_rx_is_lockedtodata_olt_1g25_inst(), .o_rx_is_lockedtoref_olt_1g25_inst(),
        .i_rx_set_locktoref_olt_1g25_inst(1'b0), .i_tx_parallel_data_olt_1g25_inst({72'b0, eth_count}),
        .o_rx_parallel_data_olt_1g25_inst(eth_rx));
endmodule
